// The listener posts the raw stream event: { resource_uri, resource_id, data, event }. Pull out what the intake needs.
// Mode is "run once for each item", so return a single { json } object, not an array.
const b = $json.body || {};
const d = b.data || {};
const m = String(b.resource_uri || '').match(/\/company\/([^/]+)\/filing-history\/([^/?#]+)/);
return { json: {
  company_number: m ? m[1] : (b.company_number || null),
  transaction_id: d.transaction_id || (m ? m[2] : b.resource_id) || null,
  type: d.type || '', category: d.category || '', description: d.description || '',
  date: d.date || null, action_date: (d.description_values && d.description_values.date) || d.action_date || null,
  capital: (d.description_values && d.description_values.capital) || null,
  doc: (d.links && d.links.document_metadata) || null,
  timepoint: b.event && b.event.timepoint, published_at: b.event && b.event.published_at
} };

// Mode is "run once for each item", so return a single { json } object, not an array.
const f = $('Pick filing fields').item.json;
let p = {}; try { p = JSON.parse(String($json.body || '{}')); } catch (e) { p = {}; }
const profile = { company_name: p.company_name, company_status: p.company_status, type: p.type, date_of_creation: p.date_of_creation, sic_codes: p.sic_codes || [], registered_office_address: p.registered_office_address, accounts: p.accounts, has_charges: p.has_charges };
return { json: { p_event: Object.assign({}, f, { profile }) } };
